package com.coopermor.highAlchPriceChecker;

import com.google.inject.Provides;
import java.text.NumberFormat;
import java.util.Locale;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "High Alch Price Checker"
)
public class HighAlchPriceCheckerPlugin extends Plugin
{

	private static final int ITEM_SLOT_COUNT = 28;

	private static final NumberFormat NUMBER_FORMAT = NumberFormat.getIntegerInstance(Locale.US);

	@Inject
	private Client client;

	@Inject
	private HighAlchPriceCheckerConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientThread clientThread;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("High Alch Price Checker started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.debug("High Alch Price Checker stopped!");
	}

	@SuppressWarnings("unused")
	@Subscribe
	private void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("highalchpricechecker") || !event.getKey().equals("displayPrice"))
		{
			return;
		}
		clientThread.invokeAtTickEnd(() ->
		{
			ItemContainer container = client.getItemContainer(InventoryID.TRADEOFFER);
			if (container == null)
			{
				return;
			}

			Item[] items = container.getItems().clone();
			recreateWidget(items);
		});
	}

	@SuppressWarnings("unused")
	@Subscribe
	private void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.TRADEOFFER)
		{
			return;
		}
		ItemContainer tradeOffer = event.getItemContainer();
		Item[] items = tradeOffer.getItems().clone();
		clientThread.invokeLater(() -> recreateWidget(items));
	}

	private int getValue(Item item)
	{
		final int canonicalId = itemManager.canonicalize(item.getId());
		ItemComposition itemDef = itemManager.getItemComposition(canonicalId);
		final int price = itemDef.getPrice();
		final boolean isAlchable = itemDef.getIntValue(295) == 0;

		switch (canonicalId)
		{
			case ItemID.COINS:
				return 1;
			case ItemID.PLATINUM:
				return 1000;
		}

		if (!isAlchable)
		{
			return 0;
		}

		switch (config.displayPrice())
		{
			case LOW:
				return price * 40 / 100;
			default:
			case HIGH:
				return price * 60 / 100;

		}
	}

	private void recreateWidget(Item[] containerItems)
	{
		Widget priceChecker = client.getWidget(InterfaceID.GePricechecker.UNIVERSE);
		if (priceChecker == null || priceChecker.isHidden())
		{
			return;
		}
		Widget itemsWidget = client.getWidget(InterfaceID.GePricechecker.ITEMS);
		if (itemsWidget == null)
		{
			return;
		}

		Widget[] children = itemsWidget.getChildren();

		if (children == null)
		{
			return;
		}

		int slots = Math.min(ITEM_SLOT_COUNT, containerItems.length);

		long combinedValue = 0;

		for (int slot = 0; slot < slots; slot++)
		{
			int widgetIndex = ITEM_SLOT_COUNT + slot;

			if (widgetIndex >= children.length)
			{
				break;
			}

			Widget valueWidget = children[widgetIndex];

			if (valueWidget == null)
			{
				continue;
			}

			Item item = containerItems[slot];

			int quantity = item.getQuantity();
			int unitValue = getValue(item);
			long totalValue = (long) quantity * unitValue;

			combinedValue += totalValue;

			valueWidget.setText(
				NUMBER_FORMAT.format(quantity)
				+ " x "
				+ NUMBER_FORMAT.format(unitValue)
				+ "<br>= "
				+ NUMBER_FORMAT.format(totalValue)
			);
		}

		Widget outputWidget = client.getWidget(InterfaceID.GePricechecker.OUTPUT);
		if (outputWidget == null)
		{
			return;
		}
		outputWidget.setText(
			"Total "
			+ config.displayPrice().toString().toLowerCase()
			+ " value:<br><col=ffffff>"
			+ NUMBER_FORMAT.format(combinedValue)
			+ "</col>"
		);
	}

	@SuppressWarnings("unused")
	@Provides
	HighAlchPriceCheckerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HighAlchPriceCheckerConfig.class);
	}
}

package com.coopermor.highAlchPriceChecker;

import lombok.AllArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("highalchpricechecker")
public interface HighAlchPriceCheckerConfig extends Config
{
	@ConfigItem(
		keyName = "displayPrice",
		name = "Price to display",
		description = "Price to use in the price check interface."
	)
	default Price displayPrice()
	{
		return Price.HIGH;
	}

	@AllArgsConstructor
	enum Price
	{
		LOW("Low alch"),
		HIGH("High alch"),
		;
		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}
}
